import {readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {balancedRoundOrder} from '../../framework-comparison/src/balanced-round-order.mjs';
import {measureSsrRequest,runSsrBurst,runSustainedSsrWindow,resetSsrClientConnections} from '../../framework-comparison/src/ssr-benchmark-client.mjs';
import {startSsrWorker,stopSsrWorker,controlSsrWorker} from '../../framework-comparison/src/ssr-worker-controller.mjs';
import {settleSsrWorkerInventoryStartup} from '../../framework-comparison/src/ssr-worker-inventory.mjs';
import {availableSsrRuntimes,measureSsrArtifact,ssrEnvironmentMetadata} from '../../framework-comparison/src/ssr-run-environment.mjs';
import {aggregateSsrThroughput,summarizeSsrSamples} from '../../framework-comparison/src/ssr-benchmark-statistics.mjs';
import {startComparisonServer} from '../../framework-comparison/src/server.mjs';
const suite=path.resolve('framework-comparison'),output=path.resolve('.tmp/exact-react-ssr/results.json');
const ids=['exact','react'],runtime=availableSsrRuntimes('node')[0];
const report={kind:'focused-exact-react-ssr',createdAt:new Date().toISOString(),throughputMethod:'deferred-validation-aggregate-v2',environment:ssrEnvironmentMetadata([runtime]),method:{populations:4,rounds:50,windowMs:500,concurrency:32,burstRequests:16,sequentialRequestsPerRound:10},artifacts:{},epochs:[],runner:await readFile(new URL('./run.mjs',import.meta.url),'utf8')};
const artifactPaths={exact:path.join(suite,'participants/exact/dist-server'),react:path.join(suite,'participants/react/dist-server'),server:path.resolve('packages/server/dist'),nodeAdapter:path.resolve('framework-adapters/node-adapter/dist')};
for(const[id,directory]of Object.entries(artifactPaths))report.artifacts[id]=await measureSsrArtifact(directory);
function validate(entry,samples){for(const sample of samples){assert.ok(sample.meaningful);assert.equal(sample.bytes,entry.identity.bytes);assert.equal(sample.hash,entry.identity.hash);}}
function summarize(samples){return Object.fromEntries(ids.map(id=>{const seq=samples.sequential.filter(s=>s.id===id),bursts=samples.bursts.filter(s=>s.id===id),windows=samples.windows.filter(s=>s.id===id);return[id,{sequential:summarizeSsrSamples(seq.map(s=>s.totalMs)),burst:summarizeSsrSamples(bursts.map(s=>s.elapsedMs)),sustained:{...aggregateSsrThroughput(windows),windowRates:summarizeSsrSamples(windows.map(s=>1000*s.requests/s.elapsedMs))}}];}));}
const service=await startComparisonServer();
try{
 for(let epoch=0;epoch<4;epoch++){
  const entries=balancedRoundOrder(ids,epoch).map(id=>({id}));
  const startup=await settleSsrWorkerInventoryStartup(entries,entry=>startSsrWorker({runtime,participantId:entry.id,transport:'node-http',workerPath:path.join(suite,'src/ssr-benchmark-worker.mjs'),workingDirectory:suite,serviceUrl:service.url}));
  try{
   if(startup.failure)throw startup.failure;
   for(const entry of entries){entry.identity=await measureSsrRequest(entry.worker.url);assert.ok(entry.identity.meaningful);validate(entry,(await runSustainedSsrWindow(entry.worker.url,32,2000)).samples);await controlSsrWorker(entry.worker,'reset');}
   const samples={epoch,identities:Object.fromEntries(entries.map(e=>[e.id,e.identity])),sequential:[],bursts:[],windows:[]};
   for(let round=0;round<50;round++)for(const entry of balancedRoundOrder(entries,round,epoch))for(let request=0;request<10;request++){const s=await measureSsrRequest(entry.worker.url);validate(entry,[s]);samples.sequential.push({id:entry.id,round,request,totalMs:s.totalMs,ttfbMs:s.ttfbMs});}
   for(const entry of entries)await controlSsrWorker(entry.worker,'reset');
   for(let round=0;round<50;round++)for(const entry of balancedRoundOrder(entries,round,epoch)){const s=await runSsrBurst(entry.worker.url,16,16);validate(entry,s.samples);samples.bursts.push({id:entry.id,round,elapsedMs:s.elapsedMs});}
   for(const entry of entries){validate(entry,(await runSustainedSsrWindow(entry.worker.url,32,2000)).samples);await controlSsrWorker(entry.worker,'reset');}
   for(let round=0;round<50;round++)for(const entry of balancedRoundOrder(entries,round,epoch)){const s=await runSustainedSsrWindow(entry.worker.url,32,500);validate(entry,s.samples);samples.windows.push({id:entry.id,round,requests:s.samples.length,elapsedMs:s.elapsedMs});}
   samples.summary=summarize(samples);report.epochs.push(samples);await writeFile(output,JSON.stringify(report,null,2));
   console.log('Population',epoch+1,Object.fromEntries(ids.map(id=>[id,{rps:samples.summary[id].sustained.aggregateRequestsPerSecond,sequentialMs:samples.summary[id].sequential.mean,burstMs:samples.summary[id].burst.mean}])));
  }finally{for(const worker of startup.workers)await stopSsrWorker(worker);resetSsrClientConnections();}
 }
 report.summary=summarize(Object.fromEntries(['sequential','bursts','windows'].map(key=>[key,report.epochs.flatMap(e=>e[key])])));
 for(const[id,directory]of Object.entries(artifactPaths))assert.deepEqual(await measureSsrArtifact(directory),report.artifacts[id]);
 report.complete=true;await writeFile(output,JSON.stringify(report,null,2));console.log('FINAL',JSON.stringify(report.summary));
}finally{await service.close();}
